#!/usr/bin/env node
/**
 * Generates src/index.ts: one named export per public .astro component, so batch ports
 * never edit a shared file. Demos and files starting with `_` are skipped.
 *   node scripts/build-index.mjs [--check]
 */
import {existsSync, readdirSync, readFileSync, writeFileSync} from 'node:fs';
import {dirname, join} from 'node:path';
import {fileURLToPath} from 'node:url';

const pkgRoot = join(dirname(fileURLToPath(import.meta.url)), '..');
const componentsDir = join(pkgRoot, 'src/components');
const lines = [
  '// @generated by scripts/build-index.mjs — do not edit manually.',
  "export {themeProps, stableClassName, dataAttributes, cx} from './lib/themeProps';",
  "export {translator, resolveLocale} from './lib/i18n';",
  "export {sanitizeUrl, isSafeUrl, safeHref} from './lib/safeUrl';",
  "export type * from './lib/types';",
  "export {registerIcons, registerIconTheme, resolveIcon, getIcon, getExtendedIcon, getIconRegistry, resolveComponentIcon, resetIcons} from './components/Icon/iconRegistry';",
  "export type * from './components/Icon/iconRegistry';",
  "export {attachTooltip, attachHoverCard} from './components/Tooltip/attach';",
  "export {attachPopover} from './components/Popover/attach';",
  "export {registerIndicatorTheme, getIndicator, defaultIndicators, resetIndicators} from './components/Indicator/indicatorRegistry';",
  "export {defineSyntaxTheme, syntaxThemeToCSS} from './components/theme/syntaxTheme';",
  "export {themeRootAttributes} from './components/theme/themeRoot';",
  "export {resolveLinkComponent, linkDestination} from './components/LinkProvider/linkComponent';",
  "export {renderWithLocals, requestLocal} from './lib/subtreeLocals';",
  "export {uid} from './lib/uid';",
  "export {routeFieldProps, statusIconPlan, textEntryTraitAttributes, joinAriaIDs, fieldId} from './components/Field/fieldProps';",
  "export {stamp, stampAttr, seal, inherits} from './lib/cascade';",
  "export {attachDialog} from './components/Dialog/attach';",
  "export {attachDrawer} from './components/Drawer/attach';",
  "export {attachBottomSheet} from './components/BottomSheet/attach';",
  "export {proportional, pixel, generateColumns, resolveColumnWidths, DEFAULT_MIN_COLUMN_WIDTH, useTableSortable, useTableSortableState, useTableColumnResize, useTableStickyColumns, useTableRowExpansion, useTableRowStatus, useTableGroupedRows, useTableTreeData, useTableTreeState, useTableRowIndex} from './components/Table/table';",
  "export type * from './components/Table/types';",
  "export {createStaticSource} from './components/Typeahead/createStaticSource';",
  '',
];
const seen = new Set();
for (const dir of readdirSync(componentsDir).sort()) {
  const files = readdirSync(join(componentsDir, dir)).filter((f) => f.endsWith('.astro') && !f.endsWith('.demo.astro') && !f.startsWith('_')).sort();
  for (const file of files) {
    const name = file.replace('.astro', '');
    if (seen.has(name)) throw new Error(`Duplicate component name ${name} (${dir}/${file})`);
    seen.add(name);
    lines.push(`export {default as ${name}} from './components/${dir}/${file}';`);
  }
}
const out = join(pkgRoot, 'src/index.ts');
const content = lines.join('\n') + '\n';
if (process.argv.includes('--check')) {
  if (!existsSync(out) || readFileSync(out, 'utf8') !== content) { console.error('stale: src/index.ts'); process.exit(1); }
} else writeFileSync(out, content);
console.log(`${seen.size} components exported`);
